{
 "summary": "Lean asserts two existence results about finitely generated, countable groups in Type 0 that are ICC and have Kazhdan property (T). (1) There are two non-isomorphic such groups Γ, Λ whose group von Neumann algebras admit a normal, trace-preserving *-isomorphism. (2) There are Λ and a sequence Γ_n of such groups, with Λ and all Γ_n pairwise non-isomorphic and all their group factors tracially isomorphic. The definitions of ICC, property (T), the left regular representation, L(G) (as a double commutant) and the canonical trace are faithful. The factor-isomorphism notion adds normality and trace-preservation, which only strengthens the existence claim. The main caveat is coverage: the 'Moreover' part of Theorem 1.2 (finite-index embeddings Γ_0 ↪ Γ_n of index 2^{4n}, commensurability) is not formalized.",
 "glossary": [
  {"decl": "CountableDiscreteGroup", "line": 7, "plain": "A countable group (discrete).", "standard_concept": "countable discrete group", "matches_standard": "yes", "note": ""},
  {"decl": "IsICC", "line": 24, "plain": "G is infinite and every nonidentity conjugacy class {xgx⁻¹} is infinite.", "standard_concept": "ICC group", "matches_standard": "yes", "note": ""},
  {"decl": "GroupsIsomorphic", "line": 27, "plain": "There exists a group isomorphism G ≅ H.", "standard_concept": "group isomorphism", "matches_standard": "yes", "note": ""},
  {"decl": "UnitaryRepresentation", "line": 30, "plain": "A group homomorphism G → U(H) for a complex Hilbert space H.", "standard_concept": "unitary representation of a discrete group", "matches_standard": "yes", "note": "No continuity is needed for discrete groups."},
  {"decl": "UnitaryRepresentation.HasAlmostInvariantUnitVectors", "line": 43, "plain": "For every finite K ⊆ G and every ε > 0 there is a unit vector ξ with ‖π(g)ξ − ξ‖ < ε for all g ∈ K.", "standard_concept": "almost invariant vectors", "matches_standard": "yes", "note": ""},
  {"decl": "HasKazhdanPropertyT", "line": 49, "plain": "Every unitary representation of G on a Hilbert space in the same universe that has almost invariant unit vectors has a nonzero invariant vector.", "standard_concept": "Kazhdan property (T)", "matches_standard": "yes", "note": "Only Hilbert spaces in Type 0 are quantified. For a countable group this is equivalent to the standard notion, since separable representations suffice."},
  {"decl": "leftRegularRepresentation", "line": 106, "plain": "λ(g)f(h) = f(g⁻¹h) on ℓ²(G).", "standard_concept": "left regular representation", "matches_standard": "yes", "note": ""},
  {"decl": "vonNeumannClosure", "line": 124, "plain": "The double commutant (S ∪ S*)''.", "standard_concept": "generated von Neumann algebra", "matches_standard": "yes", "note": ""},
  {"decl": "groupVonNeumannAlgebra", "line": 143, "plain": "L(G) = λ(G)'' ⊆ B(ℓ²G).", "standard_concept": "group von Neumann algebra L(G)", "matches_standard": "yes", "note": ""},
  {"decl": "canonicalTrace", "line": 156, "plain": "τ(x) = ⟨δ_1, x δ_1⟩.", "standard_concept": "canonical trace on L(G)", "matches_standard": "yes", "note": ""},
  {"decl": "IsNormalStarAlgEquiv", "line": 169, "plain": "The *-isomorphism and its inverse preserve suprema of arbitrary families of projections.", "standard_concept": "normal *-isomorphism", "matches_standard": "yes", "note": "Automatic for *-isomorphisms of von Neumann algebras, so it is an extra but satisfiable requirement."},
  {"decl": "TracialGroupFactorEquiv", "line": 179, "plain": "A normal, trace-preserving *-isomorphism L(G) ≅ L(H).", "standard_concept": "isomorphism of group von Neumann algebras", "matches_standard": "yes", "note": "Stronger than a bare isomorphism. For II1 factors trace preservation is automatic by uniqueness of the trace."}
 ],
 "lean_claims": [
  {"theorem": "exists_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "line": 199, "plain": "There exist countable groups Γ, Λ with the following properties: both finitely generated, both ICC, both with property (T); a normal trace-preserving *-isomorphism L(Γ) ≅ L(Λ) exists; and Γ ≇ Λ."},
  {"theorem": "exists_infinite_pairwise_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "line": 208, "plain": "There exist countable groups Λ and Γ_0, Γ_1, … with the following properties: all finitely generated, ICC, with property (T); L(Γ_n) ≅ L(Λ) and L(Γ_m) ≅ L(Γ_n) tracially for all m, n; Γ_m ≇ Γ_n for m ≠ n; and Λ ≇ Γ_n for all n."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.2", "plain": "There exist finitely generated ICC property-(T) groups Λ, Γ_0, Γ_1, … that are pairwise nonisomorphic with L(Γ_n) ≅ L(Λ). Moreover, Γ_n contains a subgroup isomorphic to Γ_0 of index 2^{4n}, so the Γ_n are commensurable."},
  {"ref": "Corollary 5.10 / disproof of Conjecture 1.1", "plain": "The pair Λ, Γ_0 consists of non-isomorphic ICC property-(T) groups with isomorphic group factors."}
 ],
 "coverage": [
  {"paper_ref": "Corollary 5.10", "lean_theorem": "exists_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "relation": "equivalent", "why": "Lean additionally demands normality and trace preservation, which are automatic for II1 factors."},
  {"paper_ref": "Theorem 1.2 (main part)", "lean_theorem": "exists_infinite_pairwise_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "relation": "equivalent", "why": "Pairwise non-isomorphism and isomorphic factors are captured; the extra Γ_m–Γ_n factor isomorphisms follow by composition."},
  {"paper_ref": "Theorem 1.2 (Moreover: index-2^{4n} subgroups, commensurability)", "lean_theorem": null, "relation": "not_formalized", "why": "No subgroup or index statement appears in Lean."}
 ],
