  {"id": "F1", "category": "coverage", "severity": "low", "decl": "exists_infinite_pairwise_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "line": 208, "paper_ref": "Theorem 1.2", "explanation": "The commensurability clause (Γ_0 embeds in Γ_n with index 2^{4n}) is omitted, so Lean covers only the main part of Theorem 1.2.", "polarity": "lean weaker", "probe_idea": "Add the conjunct ∀ n, ∃ H : Subgroup (Γ n), Nonempty (H ≃* Γ 0) ∧ H.index = 2^(4*n)."},
  {"id": "F2", "category": "definition-mismatch", "severity": "low", "decl": "TracialGroupFactorEquiv", "line": 179, "paper_ref": "Theorem 1.2", "explanation": "The isomorphism is required to be normal (preserve projection suprema) and trace-preserving. The paper only says L(Γ_n) ≅ L(Λ). This is an extra requirement inside an existential, so Lean is stronger.", "polarity": "lean stronger", "probe_idea": null},
  {"id": "F3", "category": "other", "severity": "low", "decl": "HasKazhdanPropertyT", "line": 49, "paper_ref": null, "explanation": "Property (T) quantifies only over Hilbert spaces in Type 0. This is equivalent to the standard definition for countable groups, since separable representations suffice.", "polarity": "n/a", "probe_idea": "Prove that HasKazhdanPropertyT G implies the analogous property for Hilbert spaces in Type 1."}
 ],
